// Barrel re-export for all generated types.
// Individual type files are generated by ts-rs into ./types/
// Run `cargo test -p simply-daemon ts_export` to regenerate.
//
// Until ts-rs generates the files, manually export what's needed.
// This file will be replaced by a proper barrel once ts-rs runs.

// --- Daemon API types (to be generated by ts-rs) ---

export type SessionId = string;
export type ConversationId = string;
export type DocumentId = string;
export type AssetId = string;
export type BlobHash = string;
export type TabId = string;
export type TurnId = string;
export type SpanId = string;
export type EntityId = string;
export type UserId = string;

export interface Scope {
  user_id: string | null;
}

export interface RequestContext {
  scope: Scope;
}

export type Value = unknown;

export interface SessionInfo {
  id: string;
  persistence: Persistence;
  modelId: string;
  createdAt: string;
}

export type Persistence =
  | "Ephemeral"
  | { Persistent: { conversation_id: string } };

export interface CreateSessionOptions {
  persistence: Persistence | null;
  systemPrompt: string | null;
  modelId: string | null;
  seed: SeedMessage[];
}

export interface UserMessage {
  content: InputContent[];
}

export interface SeedMessage {
  role: Role;
  content: InputContent[];
}

export type Role = "user" | "assistant" | "system";

export type InputContent =
  | { type: "text"; text: string }
  | { type: "documentRef"; id: string }
  | { type: "image"; data: string; mimeType: string }
  | { type: "audio"; data: string; mimeType: string }
  | { type: "assetRef"; assetId: string; mimeType: string };

export interface ConversationInfo {
  id: string;
  name: string | null;
  messageCount: number;
  createdAt: number;
}

export interface ResolvedMessage {
  role: Role;
  content: ResolvedContent[];
  turnId: string;
}

export type ResolvedContent =
  | { type: "text"; text: string }
  | { type: "asset_ref"; asset_id: string; blob_hash: string; mime_type: string; resolved: ContentBlock | null }
  | { type: "document_ref"; document_id: string; resolved: ContentBlock | null }
  | { type: "tool_call"; id: string; name: string; arguments: unknown; extra?: unknown }
  | { type: "tool_result"; tool_call_id: string; content: ToolResultContent[] };

export type ContentBlock =
  | { type: "text"; text: string }
  | { type: "image"; data: string; mime_type: string }
  | { type: "audio"; data: string; mime_type: string }
  | { type: "document_ref"; id: string }
  | { type: "tool_call"; id: string; name: string; arguments: unknown; extra?: unknown }
  | { type: "tool_result"; tool_call_id: string; content: ToolResultContent[] };

export type ToolResultContent =
  | { type: "text"; text: string }
  | { type: "image"; data: string; mime_type: string }
  | { type: "audio"; data: string; mime_type: string };

export interface DocumentInfo {
  id: string;
  userId: string;
  title: string;
  documentType: string;
  source: string;
  sourceId: string | null;
  tabCount: number;
  createdAt: number;
  updatedAt: number;
}

export interface DocumentDetail {
  id: string;
  title: string;
  documentType: string;
  source: string;
  sourceId: string | null;
  tabs: TabInfo[];
  createdAt: number;
  updatedAt: number;
}

export interface TabInfo {
  id: string;
  title: string;
  icon: string | null;
  parentTabId: string | null;
  tabIndex: number;
  contentMarkdown: string | null;
  createdAt: number;
  updatedAt: number;
}

export interface CreateDocumentRequest {
  title: string;
  documentType: string | null;
  content: string | null;
  sourceId: string | null;
}

export interface CreateTabRequest {
  title: string;
  content: string | null;
  parentTabId: string | null;
  tabIndex: number | null;
}

export interface UpdateTabRequest {
  content: string;
}

export interface McpServerInfo {
  id: string;
  name: string;
  url: string;
  authType: string;
  isConnected: boolean;
  needsOauthLogin: boolean;
  toolCount: number;
  status: string;
  autoConnect: boolean;
  autoRetry: boolean;
}

export interface AddMcpServerRequest {
  id: string;
  name: string;
  url: string;
  authType: string;
  authToken: string | null;
  clientId: string | null;
  clientSecret: string | null;
  scopes: string[] | null;
}

export interface RegisterEphemeralRequest {
  id: string;
  url: string;
}

export interface UpdateMcpServerRequest {
  name: string | null;
  url: string | null;
  autoConnect: boolean | null;
  autoRetry: boolean | null;
}

export interface OAuthFlowInfo {
  authUrl: string;
  state: string;
}

export interface AssetInfo {
  id: string;
  blobHash: string;
  mimeType: string;
  sizeBytes: number;
}

export interface SearchHit {
  documentId: string;
  documentTitle: string;
  documentType: string;
  tabId: string;
  chunkText: string;
  chunkIndex: number;
  score: number;
}

export interface SearchRequest {
  query: string;
  documentType: string | null;
  topK: number | null;
}

export interface ReindexStatus {
  message: string;
  tabsQueued: number;
}

export interface EmbeddingQueueStatus {
  pending: number;
  processing: number;
  completed: number;
  failed: number;
}

export interface VoiceProviderInfo {
  id: string;
  name: string;
  capabilities: string[];
}

export interface InboundEvent {
  eventType: string;
  payload: unknown;
}

export type DaemonEvent =
  | { SessionReady: { session_id: string } }
  | { UserMessage: ChatMessage }
  | { TextDelta: string }
  | { AssistantContent: ContentBlock }
  | { ToolCall: { id: string; name: string; arguments: unknown } }
  | { ToolResult: { id: string; result: unknown } }
  | "TurnComplete"
  | { EventNotification: InboundEvent }
  | { Error: string };

export interface ChatMessage {
  role: Role;
  content: ContentBlock[];
}

export interface DaemonHealth {
  status: string;
}

// MCP tool types (from rmcp)
export interface McpTool {
  name: string;
  description?: string;
  inputSchema?: unknown;
}

export interface CallToolRequestParams {
  name: string;
  arguments?: Record<string, unknown>;
}

export interface CallToolResult {
  content: unknown[];
  isError?: boolean;
}

// Model types
export interface ModelId {
  provider: string;
  model: string;
}

export interface ModelDefinition {
  id: string;
  displayName: string | null;
  capabilities: ModelCapability[];
  contextWindow: number | null;
}

export type ModelCapability =
  | "Text" | "Vision" | "AudioInput" | "Embedding"
  | "ImageGeneration" | "AudioGeneration"
  | "Tools" | "Thinking" | "Streaming" | "Private";

export interface ModelInfo {
  id: ModelId;
  definition: ModelDefinition;
}

export interface ProviderInfo {
  name: string;
  apiKeyEnv: string | null;
  baseUrlEnv: string;
}

// Voice types (from simply-voice)
export interface Audio {
  data: number[];
  sampleRate: number;
  channels: number;
}

export interface Voice {
  id: string;
  name: string;
}

// Binary types (from simply-rpc)
export interface BinaryUpload {
  data: string;
  mimeType: string;
}

export interface BinaryResponse {
  data: string;
  mimeType: string;
}
